import { constructWebhook, createMayarin } from "@mayarin/sdk";

const secretKey = process.env.MAYARIN_SECRET_KEY;
const webhookSecret = process.env.MAYARIN_WEBHOOK_SECRET;
if (!secretKey || !webhookSecret) throw new Error("Mayarin secrets are required");

const mayarin = createMayarin({
  baseUrl: "https://api.mayarin.xyz",
  secretKey,
});

type PaymentEvent = {
  readonly type: "payment.created" | "payment.state_changed" | "payment.failed";
  readonly state: string;
  readonly clearingTransactionId: string;
};

export async function POST(request: Request) {
  const payload = await request.text();
  const signature = request.headers.get("Webhook-Signature");
  if (!signature) return new Response("Missing signature", { status: 400 });

  const event = await constructWebhook<PaymentEvent>({
    payload,
    signature,
    secret: webhookSecret,
  });

  // Treat the webhook as a signal; fetch the payment before fulfilment.
  if (event.type === "payment.state_changed" && event.state === "SUCCESS") {
    const payment = await mayarin.payment.get(event.clearingTransactionId);
    await fulfil(payment);
  }

  return new Response(null, { status: 204 });
}
